package com.weatherapp.servlet;
import com.weatherapp.db.Database;import com.weatherapp.util.Json;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/api/cities") public class CitiesServlet extends BaseServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{try{requireSession(req,res);List<Map<String,Object>> a=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT CityID,CityName,CountryCode,Latitude,Longitude FROM Cities WHERE IsActive=True ORDER BY CityName");ResultSet r=p.executeQuery()){while(r.next())a.add(Map.of("id",r.getInt(1),"name",r.getString(2),"country",r.getString(3),"lat",r.getDouble(4),"lon",r.getDouble(5)));}Json.write(res,a);}catch(Exception e){res.setStatus(401);Json.write(res,Map.of("message",e.getMessage()));}}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{requireSession(req,res);Map<String,Object> b=Json.M.readValue(Json.body(req),Map.class);String n=String.valueOf(b.getOrDefault("name","" )).trim(),cc=String.valueOf(b.getOrDefault("country","IN" )).trim().toUpperCase();double lat=Double.parseDouble(String.valueOf(b.getOrDefault("lat","0"))),lon=Double.parseDouble(String.valueOf(b.getOrDefault("lon","0")));if(n.isBlank()||lat<-90||lat>90||lon<-180||lon>180)throw new Exception("Invalid city details.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO Cities(CityName,CountryCode,Latitude,Longitude,IsActive) VALUES(?,?,?,?,TRUE)")){p.setString(1,n);p.setString(2,cc);p.setDouble(3,lat);p.setDouble(4,lon);p.executeUpdate();}
            Json.write(res,Map.of("ok",true,"name",n,"country",cc,"lat",lat,"lon",lon));}catch(Exception e){res.setStatus(400);Json.write(res,Map.of("ok",false,"message",e.getMessage()));}}
 protected void doDelete(HttpServletRequest req,HttpServletResponse res)throws IOException{try{requireSession(req,res);int id=Integer.parseInt(req.getParameter("id"));try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE Cities SET IsActive=False WHERE CityID=?")){p.setInt(1,id);p.executeUpdate();}Json.write(res,Map.of("ok",true));}catch(Exception e){res.setStatus(400);Json.write(res,Map.of("ok",false,"message",e.getMessage()));}}
}
